WITH p AS (SELECT machine_id,PERCENTILE_CONT(0.5) WITHIN GROUP(ORDER BY reading) OVER(PARTITION BY machine_id) median_value FROM #OpsReadings WHERE reading IS NOT NULL),
t AS (SELECT DISTINCT machine_id,CAST(median_value AS decimal(18,2)) median_reading FROM p)
SELECT m.machine_id,t.median_reading FROM #OpsMachines m LEFT JOIN t ON t.machine_id=m.machine_id;

WITH u AS (SELECT account_id,SUM(CAST(units AS bigint)) units FROM #BillUsage WHERE used_on>='20260101' AND used_on<'20260201' GROUP BY account_id),
c AS (SELECT a.account_id,COALESCE(u.units,0) units FROM #BillAccounts a LEFT JOIN u ON u.account_id=a.account_id)
SELECT account_id,CAST(CASE WHEN units<=10 THEN units*1.0 WHEN units<=30 THEN 10+(units-10)*0.5 ELSE 20+(units-30)*0.25 END AS decimal(18,2)) usage_charge FROM c;

WITH p AS (SELECT *,LAG(ends_on) OVER(PARTITION BY account_id ORDER BY starts_on,subscription_id) previous_end FROM #BillSubscriptions)
SELECT account_id,previous_end gap_start,starts_on gap_end,DATEDIFF(day,previous_end,starts_on) gap_days
FROM p WHERE previous_end<starts_on;
